#pragma once
// Shader/pipeline precaching (docs/RENDERING.md, "Pipeline precache").
//
// Aurora compiles a render pipeline for every distinct GX state the game draws with. The
// shipped precache list (pipelines.bin next to the executable, generated by
// tools/pipelines/pipelines.py from automated sweeps) plus everything this PC has used
// before (pipeline_cache.db in the cache directory) are compiled in the background from the
// first frame on; a draw whose pipeline is not ready yet waits for it (Aurora patch 0013),
// so nothing ever flickers. Setup shows the first compile with a progress bar.
#include <cstdint>

namespace recomp::precache {
void configure();  // before aurora_initialize: worker thread count (LM_PIPELINE_THREADS)
void init();       // after aurora_initialize, before the first frame: logging, precache list, GX accuracy flags
void frame();      // host thread, once per frame (inside the ImGui frame): stats log, "compiling" indicator

struct Progress {
    uint32_t done = 0, total = 0;  // background precache
    bool finished() const { return done >= total; }
    float fraction() const { return total ? float(done) / float(total) : 1.0f; }
};
Progress progress();

// Host thread, once per main-loop iteration: true while the game must not run because the
// pipelines a rebuild of the known set queued (startup: the whole list; later: the variants a
// settings change needs, Aurora 0217) are still compiling. The game starts only after them, so
// the boot logos and the title never stutter on a compile; a settings change pauses the game
// with a progress overlay instead of stuttering in play. Test override: LM_PRECACHE_WAIT=0
// (start at once, compile in the background as before).
bool holdGame();
void drawHold();  // inside the ImGui frame while holdGame(): "Preparing shaders... n / m"
}  // namespace recomp::precache
